const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((cents||0)/100);
const num = n => new Intl.NumberFormat('en-US').format(n||0);
const title = s => String(s||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const short = s => String(s).replace(/^[A-Z]+-/,'').toUpperCase();
const date = v => v ? new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:state?.settings.timezone||'Asia/Shanghai'}).format(new Date(v.length===10?v+'T12:00:00Z':v)) : '—';
const today = () => new Intl.DateTimeFormat('en-CA',{timeZone:state?.settings.timezone||'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const pName = id => state.products.find(p=>p.id===id)?.name||id;
const pSku = id => state.products.find(p=>p.id===id)?.sku||id;
const wName = id => state.warehouses.find(w=>w.id===id)?.name||id;
const sName = id => state.suppliers.find(s=>s.id===id)?.name||id;
const docTotal = o => o.lines.reduce((a,l)=>a+l.qty*l.unitCents,0);
const permit = action => state?.permissions.includes(action);
let state, page=location.hash.slice(1)||'home', tab='', query='', searchGlobal='', statusFilter='all', sortKey='', sortDir=1, modalType='', modalRecord=null, reportData=null, period='30', busy=false;
let reportFilters={from:'',to:'',channel:'all'};
const app=$('#app');

const paths={
  home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z M9 21v-8h6v8',
  product:'m12 3 9 5-9 5-9-5 9-5z M3 8v9l9 5 9-5V8 M12 13v9',
  sales:'M4 4h2l3 12h10l2-8H7 M10 21h.01 M18 21h.01',
  fba:'M3 9h18v12H3z M2 9l10-6 10 6 M8 13v8 M16 13v8',
  purchase:'M7 3h10v4H7z M5 5H3v16h18V5h-2 M7 12h10 M7 16h6',
  warehouse:'M3 21V9l9-6 9 6v12 M3 21h18 M7 21V11h10v10 M7 15h10',
  logistics:'M1 5h13v12H1z M14 9h4l4 4v4h-8 M6 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4 M18 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4',
  advertising:'M3 10h4l13-5v14L7 14H3z M7 14l2 7h4l-2-6',
  service:'M21 11a9 9 0 0 1-9 9H4l-2 2v-9a10 10 0 0 1 19-2z M7 10h10 M7 14h6',
  finance:'M3 5h18v15H3z M3 9h18 M15 14h3 M7 14h2',
  statistics:'M4 21V11h4v10 M10 21V3h4v18 M16 21V7h4v14',
  tools:'m14 6 4-4 4 4-4 4-3-1-9 12-4-4L14 6z',
  settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 3-2 2 1 4-3 2-3-1-2 3-3-1-1-3-3-1-2-3 2-2-1-4 3-2 3 1z',
  search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',
  plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',check:'m5 12 4 4 10-10',close:'m6 6 12 12 M18 6 6 18',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',logout:'M9 3H3v18h6 M9 12h12 M16 7l5 5-5 5',alert:'m12 3 10 18H2L12 3z M12 9v5 M12 17h.01',chevron:'m9 5 7 7-7 7',filter:'M3 5h18 M6 12h12 M9 19h6',edit:'m16 3 5 5-13 13H3v-5L16 3z',refresh:'M20 7v5h-5 M4 17v-5h5 M6 6a8 8 0 0 1 14 6 M18 18A8 8 0 0 1 4 12',users:'M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M2 21v-4a5 5 0 0 1 5-5h4a5 5 0 0 1 5 5v4 M17 4a4 4 0 0 1 0 7 M19 13a5 5 0 0 1 3 4v4',
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.product}"/></svg>`;
const badge=(v)=>`<span class="badge ${esc(v)}"><i></i>${esc(title(v))}</span>`;
const btn=(label,action,id='',kind='quiet',extra='')=>`<button type="button" class="btn ${kind}" data-action="${action}" data-id="${esc(id)}" ${extra}>${esc(label)}</button>`;
const createBtn=(label,type,permission)=>permit(permission)?`<button class="btn primary" data-form="${type}">${icon('plus')}${label}</button>`:'';
const exportBtn=collection=>`<a class="btn secondary" href="/api/export/${collection}" download>${icon('download')}Export</a>`;

async function api(path,options={}) {
  const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});
  const data=await response.json();if(!response.ok){if(response.status===401&&state){state=null;renderLogin();}throw new Error(data.error||'Request failed.');}return data;
}
async function load(){state=await api('/api/bootstrap');await refreshReport();}
async function refreshReport(){
  if(period!=='custom'){
    const to=today();const fromDate=new Date(to+'T12:00:00Z');fromDate.setUTCDate(fromDate.getUTCDate()-(period==='7'?6:29));
    reportFilters={from:period==='all'?'':fromDate.toISOString().slice(0,10),to:period==='all'?'':to,channel:'all'};
  }
  const params=new URLSearchParams();for(const[k,v]of Object.entries(reportFilters))if(v)params.set(k,v);
  reportData=await api('/api/report?'+params);
}
function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),5000);}
async function action(name,payload,success='Saved successfully.') {
  if(busy)return;busy=true;
  try{await api('/api/action',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({action:name,payload})});await load();closeModal(true);render();toast(success);}
  catch(e){const error=$('.form-error');if(error){error.textContent=e.message;error.hidden=false;}else toast(e.message,'error');}
  finally{busy=false;$$('button[data-submit]').forEach(b=>{b.disabled=false;b.textContent=b.dataset.original||'Save';});}
}

function renderLogin(error='') {
  app.innerHTML=`<main class="login-page"><section class="login-story"><div class="brand big"><span class="brand-mark">H</span>harbor<span class="brand-caption">ERP</span></div><div class="login-copy"><span class="eyebrow">EVERY DETAIL. ONE WORKSPACE.</span><h1>A clear view.<br>A steady operation.</h1><p>Products, purchases, inventory, and profit.<br>Connected from the first order to the last mile.</p><div class="login-art"><div class="orbit a"></div><div class="orbit b"></div><div class="art-box one">${icon('product')}</div><div class="art-box two">${icon('warehouse')}</div><div class="art-box three">${icon('statistics')}</div><span>Built around the way your business moves.</span></div></div><div class="login-foot">LOCAL WORKSPACE <span>·</span> PERSISTENT SQLITE STORAGE</div></section><section class="login-panel"><div class="login-form-wrap"><div class="workspace-tag"><span class="online-dot"></span>Your operations workspace</div><h2>Welcome aboard.</h2><p class="muted">Sign in to your Harbor workspace.</p><form id="login-form"><label>Email address<input name="email" type="email" autocomplete="username" required value="admin@harbor.local"></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><p class="form-error" ${error?'':'hidden'}>${esc(error)}</p><button class="btn primary wide" type="submit">Open workspace ${icon('arrow')}</button></form><div class="demo-login"><strong>Explore the working example</strong><p>Example records are ready. Every change is saved locally.</p><div class="demo-roles"><button data-demo="admin">Administrator</button><button data-demo="operator">Operator</button><button data-demo="analyst">Analyst</button></div><small>Demo password: <code>HarborDemo!2026</code></small></div><p class="login-note">An independent implementation inspired by Lingxing ERP research.<br>Marketplace connections are not configured.</p></div></section></main>`;
  $$('#app [data-demo]').forEach(b=>b.onclick=()=>{const f=$('#login-form');f.email.value=b.dataset.demo+'@harbor.local';f.password.value='HarborDemo!2026';f.requestSubmit();});
  $('#login-form').onsubmit=async e=>{e.preventDefault();const f=e.target;const b=$('button[type=submit]',f);b.disabled=true;try{await api('/api/login',{method:'POST',body:JSON.stringify({email:f.email.value,password:f.password.value})});await load();render();}catch(err){renderLogin(err.message);}};
}

const nav=[['home','Overview'],['product','Product'],['sales','Sales'],['fba','FBA'],['purchase','Purchase'],['warehouse','Warehouse'],['logistics','Logistics'],['advertising','Advertising'],['service','Service'],['finance','Finance'],['statistics','Statistics'],['tools','Tools'],['settings','Settings']];
const pageInfo={home:['Your operation, at a glance.','A connected view of sales, stock, and the work ahead.'],product:['Product catalog','The details behind every product you sell.'],sales:['Sales orders','From confirmed demand to fulfilled orders.'],fba:['Fulfillment','Keep your marketplace stock moving.'],purchase:['Purchasing','Plan, approve, order, and receive with confidence.'],warehouse:['Inventory','Know what’s available, reserved, and on the move.'],logistics:['Logistics','Track every transfer from departure to arrival.'],advertising:['Advertising','Record campaign performance and keep spending in view.'],service:['Customer service','A clear queue for questions, issues, and returns.'],finance:['Finance','Reconcile costs, payments, and operating results.'],statistics:['Performance','Turn operating activity into a clearer picture.'],tools:['Operations tools','Small tools that keep the bigger picture on track.'],settings:['Workspace settings','Your company, warehouses, and access controls.']};
function tabs(items){if(!tab||!items.some(x=>x[0]===tab))tab=items[0][0];return `<div class="tabs" role="tablist">${items.map(([id,label,count])=>`<button role="tab" aria-selected="${tab===id}" class="tab ${tab===id?'active':''}" data-tab="${id}">${label}${count!=null?`<span>${count}</span>`:''}</button>`).join('')}</div>`;}
function heading(actions=''){const info=pageInfo[page]||pageInfo.home;return `<div class="page-heading"><div><div class="eyebrow">${page==='home'?'OPERATIONS / OVERVIEW':`WORKSPACE / ${esc(page.toUpperCase())}`}</div><h1>${info[0]}</h1><p>${info[1]}</p></div><div class="heading-actions">${actions}</div></div>`;}
function filters(statuses=[],hint='Search records…'){return `<div class="table-toolbar"><label class="search-field">${icon('search')}<input id="record-search" aria-label="Search records" placeholder="${hint}" value="${esc(query)}"></label><div class="toolbar-right">${statuses.length?`<label class="filter-select">${icon('filter')}<select id="status-filter" aria-label="Filter status"><option value="all">All statuses</option>${statuses.map(s=>`<option value="${s}" ${statusFilter===s?'selected':''}>${title(s)}</option>`).join('')}</select></label>`:''}<span class="table-context">${icon('check')}Saved locally</span></div></div>`;}
function filterRows(rows){const q=query.trim().toLowerCase();let list=rows.filter(x=>(statusFilter==='all'||x.status===statusFilter)&&(!q||JSON.stringify(x).toLowerCase().includes(q)||x.lines?.some(l=>pName(l.productId).toLowerCase().includes(q)||pSku(l.productId).toLowerCase().includes(q))));if(sortKey)list.sort((a,b)=>typeof a[sortKey]==='number'?(a[sortKey]-b[sortKey])*sortDir:String(a[sortKey]??'').localeCompare(String(b[sortKey]??''))*sortDir);return list;}
function table(columns,rows,{empty='No records yet.',rowId=x=>x.id}={}){
  return `<div class="table-scroll"><table><thead><tr>${columns.map(c=>`<th ${c.key?`data-sort="${c.key}" tabindex="0" role="button" aria-label="Sort by ${c.label}"`:''}>${c.label}${c.key?`<span class="sort-indicator">${sortKey===c.key?(sortDir===1?'↑':'↓'):'↕'}</span>`:''}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr data-row-id="${esc(rowId(r))}">${columns.map(c=>`<td>${c.render(r)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length}"><div class="empty-state">${icon('product')}<strong>${empty}</strong><p>${query||statusFilter!=='all'?'Try clearing your search or filters.':'Create your first record to get started.'}</p></div></td></tr>`}</tbody></table></div><div class="table-footer"><span>${rows.length} record${rows.length===1?'':'s'} ${query?'matching your search':''}</span><span>All records shown · USD</span></div>`;
}
const productCell=p=>`<div class="product-cell"><span class="product-swatch c${(state.products.indexOf(p)%6)}">${icon('product')}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.sku)}</small></div></div>`;
const docCell=o=>`<strong class="mono document-id">${esc(o.id)}</strong><small class="cell-sub">${date(o.createdAt)}</small>`;
const statCard=(label,value,caption,theme='',symbol='statistics')=>`<article class="stat-card ${theme}"><div class="stat-label">${label}<span>${icon(symbol)}</span></div><div class="stat-value">${value}</div><div class="stat-caption">${caption}</div></article>`;
function sparkline(points,cls=''){
  const max=Math.max(...points,1);const coords=points.map((v,i)=>`${i*100/(points.length-1||1)},${42-v/max*34}`).join(' ');
  return `<svg viewBox="0 0 100 46" preserveAspectRatio="none" class="sparkline ${cls}" aria-hidden="true"><polyline points="${coords}" fill="none" stroke="currentColor" stroke-width="1.8" vector-effect="non-scaling-stroke"/></svg>`;
}
function chart(r){
  const values=r.daily.length?r.daily.map(x=>x.revenueCents):[0,0];const max=Math.max(...values,1);const w=750,h=180;const xs=i=>30+i*(w-45)/(values.length-1||1),ys=v=>h-20-v/max*(h-40);const points=values.map((v,i)=>`${xs(i)},${ys(v)}`).join(' ');
  return `<svg class="revenue-chart" viewBox="0 0 800 225" role="img" aria-label="Revenue by shipping date"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#347d64" stop-opacity=".22"/><stop offset="100%" stop-color="#347d64" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="30" y1="${25+i*45}" x2="750" y2="${25+i*45}" stroke="#e9eeeb" stroke-dasharray="4 5"/><text x="758" y="${29+i*45}" fill="#87948d" font-size="10">${money(Math.round(max*(1-i/3)))}</text>`).join('')}<polygon points="${xs(0)},${h-20} ${points} ${xs(values.length-1)},${h-20}" fill="url(#chart-fill)"/><polyline points="${points}" fill="none" stroke="#347d64" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${xs(i)}" cy="${ys(v)}" r="3.2" fill="#fff" stroke="#347d64" stroke-width="2"><title>${r.daily[i]?.date||'No sales'}: ${money(v)}</title></circle>`).join('')}${r.daily.filter((_,i)=>i===0||i===r.daily.length-1||i%Math.ceil(r.daily.length/5)===0).map(d=>`<text x="${xs(r.daily.indexOf(d))}" y="204" fill="#87948d" font-size="11">${esc(d.date.slice(5))}</text>`).join('')}</svg>`;
}
function dateControls(){return `<select id="period-select" aria-label="Reporting period"><option value="30" ${period==='30'?'selected':''}>Last 30 days</option><option value="7" ${period==='7'?'selected':''}>Last 7 days</option><option value="all" ${period==='all'?'selected':''}>All time</option>${period==='custom'?'<option value="custom" selected>Custom range</option>':''}</select>`;}
function overview(){
  const r=reportData||state.report;const pending=state.purchases.filter(x=>x.status==='pending');const low=lowStocks();
  return heading(`<div class="date-chip">${icon('clock')}${date(today())}</div>${dateControls()}`)+`<div class="overview-summary"><span><span class="online-dot"></span>Workspace up to date</span><span>Example workspace · ${state.products.length} products · ${state.warehouses.length} warehouses</span></div><section class="stat-grid">${statCard('Net sales',money(r.revenueCents),'Recognized when orders ship','featured','sales')}${statCard('Gross profit',money(r.grossProfitCents),`${r.revenueCents?Math.round(r.grossProfitCents/r.revenueCents*100):0}% margin · after product cost`,'','finance')}${statCard('Inventory value',money(r.stockValueCents),'Moving average · on-hand stock','','warehouse')}${statCard('Orders shipped',num(r.orders),`${num(r.units)} units sold · net of returns`,'','logistics')}</section><div class="dashboard-grid"><section class="panel performance-panel"><div class="panel-heading"><div><h2>Sales performance</h2><p>Recognized revenue by shipping date</p></div><span class="legend-dot">Net sales</span></div>${chart(r)}<div class="chart-summary"><div><small>Average order</small><strong>${money(r.orders?Math.round(r.revenueCents/r.orders):0)}</strong></div><div><small>Product cost</small><strong>${money(r.cogsCents)}</strong></div><div><small>Operating expenses</small><strong>${money(r.expenseCents)}</strong></div></div></section><section class="panel attention-panel"><div class="panel-heading"><div><h2>Needs your attention</h2><p>A little focus goes a long way.</p></div><span class="count-circle">${pending.length+low.length+state.tickets.filter(x=>x.status!=='resolved').length}</span></div><button class="attention-row" data-navigate="purchase"><span class="attention-icon amber">${icon('purchase')}</span><span><strong>Purchase approvals</strong><small>Ready for your review</small></span><b>${pending.length}</b>${icon('chevron')}</button><button class="attention-row" data-navigate="warehouse"><span class="attention-icon rose">${icon('warehouse')}</span><span><strong>Low-stock positions</strong><small>Below product reorder point</small></span><b>${low.length}</b>${icon('chevron')}</button><button class="attention-row" data-navigate="service"><span class="attention-icon blue">${icon('service')}</span><span><strong>Open customer tickets</strong><small>Keep the conversation moving</small></span><b>${state.tickets.filter(x=>x.status!=='resolved').length}</b>${icon('chevron')}</button><div class="attention-note">${icon('check')}Purchases, sales, and stock stay connected.</div></section><section class="panel top-products"><div class="panel-heading"><div><h2>Products in focus</h2><p>Your top products by net sales.</p></div><button class="text-button" data-navigate="statistics">View performance ${icon('arrow')}</button></div>${table([{label:'Product',render:x=>productCell(state.products.find(p=>p.id===x.productId))},{label:'Units sold',render:x=>num(x.units)},{label:'Net sales',render:x=>`<strong>${money(x.revenueCents)}</strong>`},{label:'Gross margin',render:x=>`${x.revenueCents?Math.round((x.revenueCents-x.cogsCents)/x.revenueCents*100):0}%`}],r.products.slice(0,4),{rowId:x=>x.productId})}</section><section class="panel activity-panel"><div class="panel-heading"><div><h2>Recent activity</h2><p>A trail of every important change.</p></div>${icon('clock')}</div><div class="activity-list">${state.audit.slice(0,5).map(a=>`<div class="activity-item"><span class="activity-dot"></span><div><strong>${esc(title(a.action.replace('.',' ')))}</strong><small>${esc(a.actor)} · ${esc(a.reference)}</small></div><time>${date(a.at)}</time></div>`).join('')}</div></section></div>`;
}
function productsPage(){
  const rows=filterRows(state.products);
  return heading(exportBtn('products')+createBtn('Add product','product','product.create'))+`<section class="panel">${filters([], 'Search SKU, name, category…')}${table([{label:'Product / SKU',key:'name',render:productCell},{label:'Category',key:'category',render:p=>`<span class="category">${esc(p.category)}</span>`},{label:'Supplier',render:p=>esc(sName(p.supplierId))},{label:'Purchase cost',key:'costCents',render:p=>money(p.costCents)},{label:'Selling price',key:'priceCents',render:p=>money(p.priceCents)},{label:'On hand',render:p=>num(state.stocks.filter(s=>s.productId===p.id).reduce((a,s)=>a+s.onHand,0))},{label:'Reorder point',key:'reorderPoint',render:p=>p.reorderPoint},{label:'',render:p=>permit('product.update')?`<button class="icon-button" aria-label="Edit ${esc(p.sku)}" data-form="product" data-id="${p.id}">${icon('edit')}</button>`:''}],rows)}</section><div class="info-strip">${icon('product')}SKU identifies a local product; SPU groups variants. Inventory cost changes through receipts, not catalog edits.</div>`;
}
const purchaseActions=o=>{
  if(!permit('purchase.transition'))return '';
  const actions={draft:[['Submit','pending']],pending:[['Approve','approved'],['Return to draft','draft']],approved:[['Place order','ordered']],ordered:[],partial:[],received:[],cancelled:[]};
  let out=(actions[o.status]||[]).map(([l,s])=>btn(l,'purchase-transition',o.id,'small',`data-status="${s}"`)).join('');
  if(['ordered','partial'].includes(o.status))out+=`<button class="btn small primary" data-form="receive" data-id="${o.id}">Receive</button>`;
  if(permit('purchase.pay')&&!['draft','pending','cancelled'].includes(o.status)&&o.paidCents<docTotal(o))out+=`<button class="btn small" data-form="purchase-payment" data-id="${o.id}">Pay</button>`;
  if(['draft','pending','approved','ordered'].includes(o.status)&&!o.paidCents&&!o.lines.some(x=>x.received))out+=btn('Cancel','purchase-transition',o.id,'small danger-quiet',`data-status="cancelled"`);
  return `<div class="row-actions">${out}</div>`;
};
function purchasePage(){
  const tabbar=tabs([['orders','Purchase orders',state.purchases.length],['suppliers','Suppliers',state.suppliers.length]]);
  if(tab==='suppliers')return heading(exportBtn('suppliers')+createBtn('Add supplier','supplier','supplier.create'))+tabbar+`<section class="panel">${filters([], 'Search suppliers…')}${table([{label:'Supplier',key:'name',render:s=>`<strong>${esc(s.name)}</strong>`},{label:'Contact',render:s=>esc(s.contact)},{label:'Email',render:s=>esc(s.email)},{label:'Payment terms',render:s=>esc(s.terms)},{label:'Orders',render:s=>state.purchases.filter(x=>x.supplierId===s.id).length}],filterRows(state.suppliers))}</section>`;
  return heading(exportBtn('purchases')+createBtn('New purchase order','purchase','purchase.create'))+tabbar+`<section class="stat-grid compact">${statCard('Awaiting approval',state.purchases.filter(x=>x.status==='pending').length,'Review and approve purchasing')}${statCard('Awaiting receipt',state.purchases.filter(x=>['ordered','partial'].includes(x.status)).length,'Ordered · partial receipts')}${statCard('Outstanding payable',money(state.report.outstandingPurchaseCents),'Approved orders minus payments')}</section><section class="panel">${filters(['draft','pending','approved','ordered','partial','received','cancelled'],'Search order, product, supplier…')}${table([{label:'Order',render:docCell},{label:'Supplier / warehouse',render:o=>`<strong>${esc(sName(o.supplierId))}</strong><small class="cell-sub">${esc(wName(o.warehouseId))}</small>`},{label:'Items',render:o=>o.lines.map(l=>`<small class="line-summary">${esc(pSku(l.productId))} × ${l.qty} <span>${l.received} received</span></small>`).join('')},{label:'Total',render:o=>`<strong>${money(docTotal(o))}</strong><small class="cell-sub">${money(o.paidCents)} paid</small>`},{label:'Expected',key:'expectedDate',render:o=>date(o.expectedDate)},{label:'Status',key:'status',render:o=>badge(o.status)},{label:'Actions',render:purchaseActions}],filterRows(state.purchases))}</section>`;
}
function salesPage(){
  const actions=o=>{
    let a='';if(permit('sale.transition')){const next={draft:['Confirm','confirmed'],confirmed:['Ship','shipped'],shipped:['Complete','completed']}[o.status];if(next)a+=btn(next[0],'sale-transition',o.id,'small primary',`data-status="${next[1]}"`);if(['draft','confirmed'].includes(o.status)&&!o.paidCents)a+=btn('Cancel','sale-transition',o.id,'small danger-quiet',`data-status="cancelled"`);}
    if(permit('sale.pay')&&!['draft','cancelled'].includes(o.status)&&o.paidCents<docTotal(o)-o.refundCents)a+=`<button class="btn small" data-form="sale-payment" data-id="${o.id}">Record payment</button>`;
    if(permit('sale.return')&&['shipped','completed'].includes(o.status)&&o.lines.some(l=>l.returned<l.qty))a+=`<button class="btn small" data-form="return" data-id="${o.id}">Return</button>`;
    return `<div class="row-actions">${a}</div>`;
  };
  return heading(exportBtn('sales')+createBtn('New sales order','sale','sale.create'))+`<section class="stat-grid compact">${statCard('Net sales',money(state.report.revenueCents),'Shipped orders · net of returns')}${statCard('To fulfill',state.sales.filter(x=>x.status==='confirmed').length,'Confirmed and stock reserved')}${statCard('Outstanding receivable',money(state.report.outstandingSalesCents),'Confirmed orders minus payments')}</section><section class="panel">${filters(['draft','confirmed','shipped','completed','cancelled'],'Search order, customer, product…')}${table([{label:'Order',render:docCell},{label:'Customer',key:'customer',render:o=>`<strong>${esc(o.customer)}</strong><small class="cell-sub">${esc(o.channel)}</small>`},{label:'Items / warehouse',render:o=>`<small>${o.lines.map(l=>`${esc(pSku(l.productId))} × ${l.qty}`).join('<br>')}</small><small class="cell-sub">${esc(wName(o.warehouseId))}</small>`},{label:'Net total',render:o=>`<strong>${money(docTotal(o)-o.refundCents)}</strong>${o.refundCents?`<small class="cell-sub">${money(o.refundCents)} returned</small>`:''}`},{label:'Payment',render:o=>badge(o.paidCents>=docTotal(o)-o.refundCents&&o.status!=='draft'?'paid':o.paidCents?'partial':'unpaid')},{label:'Status',key:'status',render:o=>badge(o.status)},{label:'Actions',render:actions}],filterRows(state.sales))}</section>`;
}
function lowStocks(){return state.stocks.filter(r=>r.onHand-r.locked<(state.products.find(p=>p.id===r.productId)?.reorderPoint||0));}
function inventoryPage(){
  const tabbar=tabs([['stock','Stock positions',state.stocks.length],['movements','Movement ledger',state.movements.length],['warehouses','Warehouses',state.warehouses.length]]);
  if(tab==='warehouses')return heading(createBtn('Add warehouse','warehouse','warehouse.create'))+tabbar+`<div class="warehouse-cards">${state.warehouses.map(w=>`<section class="panel warehouse-card"><span class="warehouse-symbol">${icon('warehouse')}</span>${badge(w.type)}<h2>${esc(w.name)}</h2><p>${esc(w.location)}</p><div class="warehouse-totals"><div><small>On-hand units</small><strong>${num(state.stocks.filter(x=>x.warehouseId===w.id).reduce((a,x)=>a+x.onHand,0))}</strong></div><div><small>Inventory value</small><strong>${money(state.stocks.filter(x=>x.warehouseId===w.id).reduce((a,x)=>a+x.onHand*x.averageCostCents,0))}</strong></div></div></section>`).join('')}</div>`;
  if(tab==='movements')return heading(exportBtn('movements'))+tabbar+`<section class="panel">${filters([], 'Search product, movement, reference…')}${table([{label:'Date',key:'createdAt',render:x=>date(x.createdAt)},{label:'Product',render:x=>`<strong>${esc(pSku(x.productId))}</strong>`},{label:'Warehouse',render:x=>esc(wName(x.warehouseId))},{label:'Movement',render:x=>badge(x.kind)},{label:'Quantity',render:x=>`<strong class="${x.delta>0?'positive':'negative'}">${x.delta>0?'+':''}${x.delta}</strong>`},{label:'Unit cost',render:x=>money(x.unitCostCents)},{label:'Reference / reason',render:x=>esc(x.reference)},{label:'After',render:x=>num(x.onHandAfter)}],filterRows(state.movements))}</section>`;
  const rows=filterRows(state.stocks.map(s=>({...s,sku:pSku(s.productId),name:pName(s.productId),warehouse:wName(s.warehouseId)})));
  return heading(exportBtn('stocks')+createBtn('Adjust inventory','adjust','inventory.adjust'))+tabbar+`<section class="stat-grid compact">${statCard('Available units',num(state.stocks.reduce((a,x)=>a+x.onHand-x.locked,0)),'On hand minus reserved')}${statCard('Reserved units',num(state.stocks.reduce((a,x)=>a+x.locked,0)),'Confirmed sales and shipments')}${statCard('In-transit value',money(state.report.transitValueCents),'Dispatched, not yet received')}</section><section class="panel">${filters([], 'Search SKU, name, warehouse…')}${table([{label:'Product',render:x=>productCell(state.products.find(p=>p.id===x.productId))},{label:'Warehouse',key:'warehouse',render:x=>esc(x.warehouse)},{label:'On hand',key:'onHand',render:x=>num(x.onHand)},{label:'Reserved',key:'locked',render:x=>num(x.locked)},{label:'Available',render:x=>`<strong>${num(x.onHand-x.locked)}</strong>`},{label:'Average cost',key:'averageCostCents',render:x=>money(x.averageCostCents)},{label:'Stock value',render:x=>money(x.onHand*x.averageCostCents)},{label:'Health',render:x=>badge(x.onHand-x.locked<state.products.find(p=>p.id===x.productId).reorderPoint?'low_stock':'healthy')}],rows)}</section>`;
}
function shipmentTable(){return table([{label:'Shipment',render:docCell},{label:'Route',render:s=>`<strong>${esc(wName(s.sourceId))}</strong><small class="cell-sub">→ ${esc(wName(s.destinationId))}</small>`},{label:'Items',render:s=>s.lines.map(l=>`<small class="line-summary">${esc(pSku(l.productId))} × ${l.qty}</small>`).join('')},{label:'Carrier / tracking',render:s=>`<strong>${esc(s.carrier)}</strong><small class="cell-sub">${esc(s.tracking||'Not assigned')}</small>`},{label:'Freight',render:s=>money(s.freightCents)},{label:'ETA',key:'expectedDate',render:s=>date(s.expectedDate)},{label:'Status',key:'status',render:s=>badge(s.status)},{label:'Actions',render:s=>{
  if(!permit('shipment.transition'))return '';const next={draft:['Reserve stock','reserved'],reserved:['Dispatch','in_transit'],in_transit:['Receive transfer','received']}[s.status];return `<div class="row-actions">${next?btn(next[0],'shipment-transition',s.id,'small primary',`data-status="${next[1]}"`):''}${['draft','reserved'].includes(s.status)?btn('Cancel','shipment-transition',s.id,'small danger-quiet','data-status="cancelled"'):''}</div>`;
}}],filterRows(state.shipments),{empty:'No transfers yet.'});}
function shipmentsPage(){return heading(exportBtn('shipments')+createBtn('Create transfer','shipment','shipment.create'))+`<section class="stat-grid compact">${statCard('Planned transfers',state.shipments.filter(x=>['draft','reserved'].includes(x.status)).length,'Prepare and reserve available stock')}${statCard('In transit',state.shipments.filter(x=>x.status==='in_transit').length,'Waiting for destination receipt')}${statCard('Received',state.shipments.filter(x=>x.status==='received').length,'Stock available at destination')}</section><section class="panel">${filters(['draft','reserved','in_transit','received','cancelled'],'Search carrier, tracking, shipment…')}${shipmentTable()}</section><div class="info-strip">${icon('logistics')}Internal warehouse transfers preserve product cost. Freight is tracked here; record it as an expense separately. Amazon STA and carrier APIs are not connected.</div>`;}
function fbaPage(){
  const tabbar=tabs([['replenishment','Replenishment'],['transfers','Transfers'],['fba-stock','FBA stock']]);
  if(tab==='transfers')return shipmentsPage()+tabbar;
  const rows=state.stocks.filter(r=>state.warehouses.find(w=>w.id===r.warehouseId).type==='fba').map(r=>({...r,product:state.products.find(p=>p.id===r.productId)}));
  if(tab==='fba-stock')return heading()+tabbar+`<section class="panel">${table([{label:'Product',render:r=>productCell(r.product)},{label:'Warehouse',render:r=>esc(wName(r.warehouseId))},{label:'On hand',render:r=>num(r.onHand)},{label:'Reserved',render:r=>num(r.locked)},{label:'Available',render:r=>num(r.onHand-r.locked)},{label:'Value',render:r=>money(r.onHand*r.averageCostCents)}],rows)}</section>`;
  const needs=rows.filter(r=>r.onHand-r.locked<r.product.reorderPoint);
  return heading()+tabbar+`<div class="info-strip">${icon('alert')}Suggestions use a transparent local rule: replenish to twice the product reorder point. This is not Lingxing’s forecasting algorithm.</div><section class="panel">${table([{label:'Product',render:r=>productCell(r.product)},{label:'Destination',render:r=>esc(wName(r.warehouseId))},{label:'Available',render:r=>r.onHand-r.locked},{label:'Reorder point',render:r=>r.product.reorderPoint},{label:'Suggested quantity',render:r=>`<strong>${r.product.reorderPoint*2-(r.onHand-r.locked)}</strong>`},{label:'Lead time',render:r=>`${r.product.leadDays} days`},{label:'',render:r=>permit('shipment.create')?`<button class="btn small primary" data-form="shipment" data-product="${r.productId}" data-destination="${r.warehouseId}" data-qty="${r.product.reorderPoint*2-(r.onHand-r.locked)}">Plan transfer</button>`:''}],needs,{empty:'FBA positions are above their reorder points.'})}</section>`;
}
function advertisingPage(){return heading(createBtn('Record campaign','campaign','campaign.create'))+`<div class="info-strip">${icon('advertising')}Campaigns are manually recorded. Pausing changes the local record only. Campaign spend is not automatically booked as a finance expense.</div><section class="panel">${filters([], 'Search campaign or channel…')}${table([{label:'Campaign',key:'name',render:c=>`<strong>${esc(c.name)}</strong><small class="cell-sub">${esc(c.channel)} · manual record</small>`},{label:'Budget',render:c=>money(c.budgetCents)},{label:'Spend',render:c=>money(c.spendCents)},{label:'Attributed sales',render:c=>money(c.attributedSalesCents)},{label:'ACOS',render:c=>c.attributedSalesCents?`${(c.spendCents/c.attributedSalesCents*100).toFixed(1)}%`:'—'},{label:'ROAS',render:c=>c.spendCents?`${(c.attributedSalesCents/c.spendCents).toFixed(2)}×`:'—'},{label:'Status',render:c=>badge(c.status)},{label:'',render:c=>permit('campaign.update')?btn(c.status==='active'?'Pause':'Activate','campaign-status',c.id,'small',`data-status="${c.status==='active'?'paused':'active'}"`):''}],filterRows(state.campaigns))}</section>`;}
function servicePage(){return heading(exportBtn('tickets')+createBtn('New ticket','ticket','ticket.create'))+`<section class="panel">${filters(['open','in_progress','resolved'],'Search customer, subject, ticket…')}${table([{label:'Ticket',render:docCell},{label:'Subject / customer',render:t=>`<strong>${esc(t.subject)}</strong><small class="cell-sub">${esc(t.customer)} ${t.orderId?'· '+esc(t.orderId):''}</small>`},{label:'Category',render:t=>esc(t.category)},{label:'Priority',render:t=>badge(t.priority)},{label:'Status',key:'status',render:t=>badge(t.status)},{label:'Notes',render:t=>t.notes.length},{label:'Actions',render:t=>`<div class="row-actions">${btn('View notes','ticket-view',t.id,'small')}${permit('ticket.transition')?btn(t.status==='resolved'?'Reopen':t.status==='open'?'Start':'Resolve','ticket-status',t.id,'small primary',`data-status="${t.status==='resolved'?'open':t.status==='open'?'in_progress':'resolved'}"`):''}</div>`}],filterRows(state.tickets))}</section><div class="info-strip">${icon('service')}Tickets and notes are internal records. No emails or marketplace messages are sent.</div>`;}
function financePage(){
  const tabbar=tabs([['summary','Overview'],['payments','Payments',state.payments.length],['expenses','Expenses',state.expenses.length]]);
  if(tab==='payments')return heading(exportBtn('payments'))+tabbar+`<section class="panel">${filters([], 'Search payment or document…')}${table([{label:'Payment',render:docCell},{label:'Direction',render:p=>badge(p.kind)},{label:'Document',render:p=>`<strong class="mono">${esc(p.reference)}</strong>`},{label:'Amount',key:'amountCents',render:p=>`<strong class="${p.kind==='inflow'?'positive':'negative'}">${p.kind==='inflow'?'+':'−'}${money(p.amountCents)}</strong>`},{label:'Date',key:'date',render:p=>date(p.date)},{label:'Note',render:p=>esc(p.note)},{label:'Recorded by',render:p=>esc(p.actor)}],filterRows(state.payments))}</section>`;
  if(tab==='expenses')return heading(exportBtn('expenses')+createBtn('Record expense','expense','expense.create'))+tabbar+`<section class="panel">${filters([], 'Search description or category…')}${table([{label:'Expense',render:docCell},{label:'Description',render:e=>`<strong>${esc(e.description)}</strong>`},{label:'Category',key:'category',render:e=>esc(e.category)},{label:'Date',key:'date',render:e=>date(e.date)},{label:'Amount',key:'amountCents',render:e=>money(e.amountCents)}],filterRows(state.expenses))}</section>`;
  const r=state.report;
  return heading(createBtn('Record expense','expense','expense.create'))+tabbar+`<section class="stat-grid">${statCard('Net sales',money(r.revenueCents),'Shipped sales less all returns','featured')}${statCard('Gross profit',money(r.grossProfitCents),'Sales less captured product cost')}${statCard('Expenses',money(r.expenseCents),'Recorded operating expenses')}${statCard('Net operating profit',money(r.netProfitCents),'Gross profit less expenses')}</section><div class="two-columns"><section class="panel"><div class="panel-heading"><h2>Outstanding balances</h2></div><div class="balance-row"><span>Accounts receivable</span><strong>${money(r.outstandingSalesCents)}</strong></div><div class="balance-row"><span>Accounts payable</span><strong>${money(r.outstandingPurchaseCents)}</strong></div><div class="balance-row"><span>On-hand inventory</span><strong>${money(r.stockValueCents)}</strong></div><div class="balance-row"><span>Inventory in transit</span><strong>${money(r.transitValueCents)}</strong></div></section><section class="panel finance-definition"><h2>A consistent view of profit.</h2><p>Revenue is recognized when an order ships. Product cost is captured from moving-average inventory at that moment. Returns reverse both sales and cost.</p><p>Expenses reduce operating profit. Payment records affect receivables and payables, not revenue recognition.</p><small>USD only · no tax, marketplace fees, FX, or statutory accounting</small></section></div>`;
}
function statisticsPage(){const r=reportData||state.report;return heading(`${dateControls()}<button class="btn secondary" data-action="export-report">${icon('download')}Export report</button>`)+`<div class="report-filter"><label>From<input type="date" id="report-from"></label><label>To<input type="date" id="report-to"></label><label>Channel<select id="report-channel"><option value="all">All channels</option>${['Amazon','Shopify','Direct','Wholesale'].map(x=>`<option>${x}</option>`).join('')}</select></label><button class="btn primary" data-action="apply-report">Apply filters</button><span>Reporting by shipment date · returns restate the original sale</span></div><section class="stat-grid compact">${statCard('Net sales',money(r.revenueCents),'After returned units')}${statCard('Units sold',num(r.units),`${r.orders} shipped orders`)}${statCard('Gross margin',`${r.revenueCents?((r.grossProfitCents/r.revenueCents)*100).toFixed(1):0}%`,'Net sales less product cost')}</section><section class="panel"><div class="panel-heading"><div><h2>Product performance</h2><p>Local SKU is the supported aggregation dimension.</p></div><span class="category">USD</span></div>${chart(r)}${table([{label:'Product',render:p=>productCell(state.products.find(x=>x.id===p.productId))},{label:'Units',render:p=>num(p.units)},{label:'Net sales',render:p=>money(p.revenueCents)},{label:'Product cost',render:p=>money(p.cogsCents)},{label:'Gross profit',render:p=>`<strong>${money(p.revenueCents-p.cogsCents)}</strong>`},{label:'Margin',render:p=>p.revenueCents?`${((p.revenueCents-p.cogsCents)/p.revenueCents*100).toFixed(1)}%`:'—'}],r.products,{rowId:p=>p.productId})}</section>`;}
